cands = {
 "bracketed": "[Berlin] is the capital of Germany.",
 "Cloze+bracketed": "Cloze[Berlin] is the capital of Germany.",
 "fam+05": None,
}
# binary combos
bs = []
for sfmt in ["<Q","<I","<q","<i",">Q",">I"]:
    bs.append(fam + struct.pack(sfmt,0) + struct.pack(sfmt,5))
    bs.append(fam + struct.pack(sfmt,0))
    bs.append(struct.pack(sfmt,0)+struct.pack(sfmt,5)+t.encode())
    bs.append(b"Cloze"+t.encode()+struct.pack(sfmt,0)+struct.pack(sfmt,5))
    bs.append(b"Cloze"+struct.pack(sfmt,0)+struct.pack(sfmt,5)+t.encode())
for k,v in cands.items():
    if v is not None and blake3(v.encode()).hex()==tc: print("MATCH", k, repr(v))
for b in bs:
    if blake3(b).hex()==tc: print("MATCH bin", b)
# maybe hash of "Cloze" + text + str(start)+str(end) with variations incl. end-exclusive 6
for s,e in [(0,5),(0,6)]:
    for v in [f"Cloze{t}{s}{e}", f"Cloze{t}{s},{e}", f"Cloze{t}{s}:{e}", f"Cloze{t}{s}-{e}",
