import math

W = [0.40255, 1.18385, 3.173, 15.69105, 7.1949, 0.5345, 1.4604, 0.0046,
     1.54575, 0.1192, 1.01925, 1.9395, 0.11, 0.29605, 2.2698, 0.2315, 2.9898]
DECAY = -0.5
FACTOR = 19/81
RETENTION = 0.9

def clamp(x, lo, hi):
    return max(lo, min(hi, x))

def init_stability(g):
    return W[g-1]

def init_difficulty(g):
    return clamp(W[4] - math.exp((g-1)*W[5]) + 1, 1.0, 10.0)

def next_difficulty(d, g):
    delta = -W[6] * (g - 3) * (10.0 - d) / 9.0
    nd = d + delta
    nd = W[7] * init_difficulty(4) + (1.0 - W[7]) * nd
    return clamp(nd, 1.0, 10.0)

def retrievability(s, elapsed):
    return (1.0 + FACTOR * elapsed / s) ** DECAY

def next_recall_stability(d, s, r, g):
    hard = W[15] if g == 2 else 1.0
    easy = W[16] if g == 4 else 1.0
    return s * (1.0 + math.exp(W[8]) * (11.0 - d) * s ** (-W[9]) * (math.exp((1.0 - r) * W[10]) - 1.0) * hard * easy)

def next_forget_stability(d, s, r):
    return min(W[11] * d ** (-W[12]) * ((s + 1.0) ** W[13] - 1.0) * math.exp(W[14] * (1.0 - r)), s)

def next_interval(s):
    return s / FACTOR * (RETENTION ** (1.0 / DECAY) - 1.0)

def review(s, d, elapsed, g):
    """returns (S', D', interval_raw, interval_days)"""
    r = retrievability(s, elapsed)
    nd = next_difficulty(d, g)
    if g == 1:
        ns = next_forget_stability(d, s, r)
    else:
        ns = next_recall_stability(d, s, r, g)
    raw = next_interval(ns)
    days = max(1, round(raw))
    return ns, nd, raw, days
